import{_ as n,o as t,c as e,a5 as i}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"04 — Media Package & Contract (Package → Campaign → Content Request)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/04-media-package-campaign.md","filePath":"ba/04-media-package-campaign.md"}'),c={name:"ba/04-media-package-campaign.md"};function h(g,a,o,r,s,l){return t(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="_04-—-media-package-contract-package-→-campaign-→-content-request" tabindex="-1">04 — Media Package &amp; Contract (Package → Campaign → Content Request) <a class="header-anchor" href="#_04-—-media-package-contract-package-→-campaign-→-content-request" aria-label="Permalink to &quot;04 — Media Package &amp; Contract (Package → Campaign → Content Request)&quot;">​</a></h1><p>&gt; <a href="./00-overview.html">&lt;&lt; Về Overview</a></p><p>&gt; <strong>Cập nhật theo xác nhận người dùng 2026-10:</strong> Flow triển khai hiện hành nằm tại &gt; <a href="./../feature/media-package-campaign/README.html">Media Package baseline</a> và &gt; <a href="./../feature/media-package-campaign/offering-models/spec.html">Offering models</a>. &gt; Workspace đã có Client khi tạo; Client chọn gói khả dụng của Agency. Dùng một bảng &gt; media_packages (Admin template global; Agency package scoped). Các đoạn tháng 9 bên dưới &gt; về chọn gói trước khi mời Client và hai bảng riêng là lịch sử, không còn dùng để triển khai. &gt; Workshop chỉ hỗ trợ tạo link Meet và survey; Event chỉ bàn giao kế hoạch sự kiện.</p><p>&gt; <strong>BA mới nhất — 2026-10-08:</strong> một Workspace gắn với một Campaign. Chiến dịch mới &gt; dùng Workspace mới; Owner có tính năng Nhân bản Workspace để chọn thông tin/tài nguyên &gt; từ Workspace cũ. Quyết định này thay thế đề xuất nhiều đợt trong cùng Workspace. &gt; Task giữ Mongo V2; Client góp ý, Manager sửa và hai bên duyệt lại; Manager mark Campaign &gt; completed. Gói mới tính tổng sản lượng; thêm Task EVENT_PLAN/PRESS_RECOMMENDATION; &gt; complete khi Task chưa xong phải có lý do và không đổi trạng thái Task con. Phạm vi &gt; Duplicate Workspace đã chốt DA-1255: chọn từng thành viên và tùy chọn copy timezone; &gt; tài nguyên chờ module riêng. Thiết kế Campaign đã ghi trong phase-1-design của feature. &gt; Xem <a href="./../feature/media-package-campaign/campaign-delivery-plan.html">lộ trình Campaign</a>.</p><h2 id="_1-thu-tu-chuan-workspace-→-package-→-campaign-→-task" tabindex="-1">1. Thứ tự chuẩn: Workspace → Package → Campaign → Task <a class="header-anchor" href="#_1-thu-tu-chuan-workspace-→-package-→-campaign-→-task" aria-label="Permalink to &quot;1. Thứ tự chuẩn: Workspace → Package → Campaign → Task&quot;">​</a></h2><p><strong>[CONFIRMED 2026-09-14]</strong> — đây là điểm quan trọng nhất của file này, đảo ngược cách đọc thẳng câu chữ CSV gốc.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Owner tạo Workspace + gán Manager (xem 01-organization-structure.md)</span></span>
<span class="line"><span>2. Manager chọn 1 Media Package template ngay sau khi tạo workspace</span></span>
<span class="line"><span>3. Manager invite Client vào Workspace</span></span>
<span class="line"><span>4. Client + Manager/Owner đàm phán Media Package (bên trong Workspace)</span></span>
<span class="line"><span>5. Cả 2 bên Approve Media Package  → &quot;hợp đồng khung&quot;</span></span>
<span class="line"><span>6. Agency tạo Media Campaign (chi tiết, bám brand Client)</span></span>
<span class="line"><span>7. Cả 2 bên Approve Media Campaign</span></span>
<span class="line"><span>8. Toàn bộ đầu việc trong Campaign → tự động đẩy thành Task backlog trong Workspace</span></span></code></pre></div><p><strong>Điểm khác so với đọc thẳng câu chữ CSV gốc:</strong> FR 3.5.1 viết &quot;khi tạo Workspace bắt buộc phải có template media package khi Owner chưa nhập thì thông báo Manager&quot; — dễ đọc nhầm là Package phải tồn tại trước khi Workspace được tạo ra. Đã confirm thực tế: <strong>Workspace tạo trước</strong> (Owner + gán Manager), Package là bước Manager làm ngay sau đó, trước khi mời Client vào — không phải điều kiện tiên quyết để ĐƯỢC tạo Workspace.</p><h2 id="_2-media-package-fr-3-5-1-–-3-5-4" tabindex="-1">2. Media Package (FR 3.5.1 – 3.5.4) <a class="header-anchor" href="#_2-media-package-fr-3-5-1-–-3-5-4" aria-label="Permalink to &quot;2. Media Package (FR 3.5.1 – 3.5.4)&quot;">​</a></h2><h3 id="_3-5-1-—-create-media-package" tabindex="-1">3.5.1 — Create Media Package <a class="header-anchor" href="#_3-5-1-—-create-media-package" aria-label="Permalink to &quot;3.5.1 — Create Media Package&quot;">​</a></h3><ul><li>Admin tạo sẵn các package mẫu (2 tuần, 3 tuần...) từ trước.</li><li>Owner có thể <strong>chọn package mẫu có sẵn</strong> hoặc <strong>custom thêm gói truyền thông mới</strong> riêng cho Agency của mình.</li><li>Không yêu cầu scheduled reminder chọn Package (xác nhận 2026-10-13); giữ gate/redirect chọn và chốt Package hiện có. Mô tả reminder cũ không còn dùng để triển khai.</li><li>Template Package cần dễ tùy chỉnh theo ý Client (mức độ dễ nhất để thay đổi).</li><li><strong>Thiết kế DB đề xuất từ nguồn</strong>: tạo 2 bảng riêng — 1 bảng cho package do Owner tạo, 1 bảng cho package custom. Cột &quot;chọn media package&quot; trong Workspace chỉ cần lưu <strong>ID tham chiếu</strong> tới 1 trong 2 bảng đó — giảm độ phức tạp và tăng tốc truy vấn (không JOIN nhiều tầng).</li><li>Role: OWNER/MANAGER.</li></ul><h3 id="_3-5-2-—-view-the-template-media-package" tabindex="-1">3.5.2 — View the Template Media Package <a class="header-anchor" href="#_3-5-2-—-view-the-template-media-package" aria-label="Permalink to &quot;3.5.2 — View the Template Media Package&quot;">​</a></h3><ul><li>Client xem được các package mẫu (chiến lược truyền thông dài/ngắn) để hiểu quy mô triển khai, nhân sự, hình dung được sẽ book Agency trong bao lâu.</li><li>Package chia theo nhiều kiểu: <ul><li>Theo <strong>khoảng thời gian</strong>: trong X tuần sẽ làm những gì.</li><li>Theo <strong>ngân sách</strong>: với số tiền Y sẽ làm được những gì.</li><li><strong>Phó mặc toàn bộ</strong>: Agency tự quyết cách làm, miễn đạt KPI đã thỏa thuận.</li></ul></li><li>Role: OWNER/MANAGER/CLIENT.</li></ul><h3 id="_3-5-3-—-request-media-package" tabindex="-1">3.5.3 — Request Media Package <a class="header-anchor" href="#_3-5-3-—-request-media-package" aria-label="Permalink to &quot;3.5.3 — Request Media Package&quot;">​</a></h3><ul><li>Với package mẫu do Agency cung cấp, <strong>Client được quyền thảo luận lại</strong>: đưa ra yêu cầu về giá, thời gian, sự kiện, hình thức...</li><li>Owner/Manager phản hồi: chấp nhận, từ chối, hoặc chuyển đổi thành 1 đề xuất khác phù hợp hơn.</li><li>Quá trình lặp lại (negotiate qua lại) <strong>cho đến khi cả 2 bên chốt được gói cuối cùng</strong>.</li><li>Role: OWNER/MANAGER/CLIENT.</li></ul><h3 id="_3-5-4-—-approve-media-package" tabindex="-1">3.5.4 — Approve Media Package <a class="header-anchor" href="#_3-5-4-—-approve-media-package" aria-label="Permalink to &quot;3.5.4 — Approve Media Package&quot;">​</a></h3><ul><li>Khi package đã đúng thỏa thuận của cả 2 bên → <strong>cả 2 bên cùng đồng ý</strong> với yêu cầu và các chỉnh sửa đã thống nhất.</li><li>Role: OWNER/MANAGER/CLIENT.</li></ul><h2 id="_3-media-campaign-fr-3-5-5-–-3-5-6" tabindex="-1">3. Media Campaign (FR 3.5.5 – 3.5.6) <a class="header-anchor" href="#_3-media-campaign-fr-3-5-5-–-3-5-6" aria-label="Permalink to &quot;3. Media Campaign (FR 3.5.5 – 3.5.6)&quot;">​</a></h2><p>&gt; <strong>Xác nhận mới 2026-10-14 — ưu tiên hơn mô tả lịch sử bên dưới:</strong> Task sinh khi chấp nhận Content Request gắn Campaign hiện tại và giữ nguồn Request; hiển thị nhóm đầu việc bổ sung, không sửa sản lượng/kế hoạch đã duyệt. Manager không thể hoàn thành khi còn Task khác COMPLETED/CANCELLED hoặc Request IN_PROGRESS. Manager có thể chọn nhiều Task chưa kết thúc (kể cả chờ QC/Client) và hủy với một lý do chung từ danh sách/Khác, lưu audit từng Task. PENDING vẫn tự hủy khi hoàn thành thành công. Xem <a href="./../feature/media-package-campaign/campaign-closure/spec.html">Campaign closure</a>. Quy tắc này thay thế campaignId=null cho Task Request mới và cách hoàn thành chỉ cần lý do khi Task chưa xong.</p><h3 id="_3-5-5-—-create-media-campaign" tabindex="-1">3.5.5 — Create Media Campaign <a class="header-anchor" href="#_3-5-5-—-create-media-campaign" aria-label="Permalink to &quot;3.5.5 — Create Media Campaign&quot;">​</a></h3><ul><li>Dựa trên Media Package đã chọn và thống nhất giữa 2 bên, nhưng <strong>chi tiết hơn</strong> — có nội dung triển khai phù hợp với brand cụ thể của Client.</li><li><strong>Quan trọng</strong>: Media Campaign <strong>KHÔNG phải là hợp đồng</strong> — nó là <strong>chiến lược thực hiện</strong> (execution strategy/plan).</li><li>Role: OWNER/MANAGER/CLIENT.</li></ul><h3 id="_3-5-6-—-approve-media-campaign" tabindex="-1">3.5.6 — Approve Media Campaign <a class="header-anchor" href="#_3-5-6-—-approve-media-campaign" aria-label="Permalink to &quot;3.5.6 — Approve Media Campaign&quot;">​</a></h3><ul><li>Sau khi đưa chiến lược ra và cả 2 bên đồng ý → tiến hành nhấn <strong>triển khai</strong>.</li><li>Toàn bộ công việc trong Media Campaign được <strong>đẩy tự động vào Workspace, tạo thành bảng backlog công việc</strong> (giống Jira backlog).</li><li><strong>Lưu ý mức độ chi tiết ở giai đoạn này</strong>: backlog sinh ra CHƯA đầy đủ quy trình triển khai, chưa có yêu cầu cụ thể — chỉ mới là tên công việc + thời gian thông thường. Chi tiết hóa xảy ra ở bước Identify Task Detail (xem <a href="./05-content-task-workflow.html">05-content-task-workflow.md</a>).</li><li><strong>[CONFIRMED 2026-09-15]</strong> Sau khi approved và đã đẩy backlog, Campaign <strong>immutable</strong> — không sửa lại được. Muốn thêm nội dung giữa chiến dịch → dùng Content Request (mục 4 dưới) hoặc Manager add Task thủ công (FR 3.6.10), không amend Campaign gốc.</li><li><strong>[CONFIRMED 2026-09-17]</strong> Với khối lượng công việc lớn phát sinh giữa chiến dịch (không phải 1 task lẻ) — dùng <strong>Campaign Addendum</strong>: bản bổ sung link tới Campaign gốc, đi qua chu trình duyệt 2 phía riêng, tách biệt Manual Task đơn lẻ ra khỏi Campaign có nguồn gốc rõ ràng để phục vụ báo cáo/billing. Xem chi tiết state machine tại <a href="./12-state-machines.html">12-state-machines.md</a> mục 3, entity tại <a href="./11-data-entities-glossary.html">11-data-entities-glossary.md</a>.</li><li>Role: OWNER/MANAGER/CLIENT.</li></ul><h2 id="_4-content-request-—-kenh-bo-sung-rieng-fr-3-5-7-–-3-5-10" tabindex="-1">4. Content Request — kênh bổ sung riêng (FR 3.5.7 – 3.5.10) <a class="header-anchor" href="#_4-content-request-—-kenh-bo-sung-rieng-fr-3-5-7-–-3-5-10" aria-label="Permalink to &quot;4. Content Request — kênh bổ sung riêng (FR 3.5.7 – 3.5.10)&quot;">​</a></h2><p>&gt; <strong>Quyết định người dùng 2026-10-14 (cần đồng bộ với team):</strong> chỉ Client thuộc Workspace có Campaign IN_PROGRESS và deployment SUCCEEDED được tạo Request. Client sửa title/description/type/dueDate hoặc hủy khi PENDING. Deadline từ ngày hiện tại, không trước ngày bắt đầu và không sau ngày kết thúc Campaign, theo timezone Workspace. Manager chủ động tiếp nhận để chuyển IN_PROGRESS và khóa sửa/hủy của Client; sau đó ACCEPTED hoặc DENIED. Hủy là CANCELLED, không xóa. Request được chấp nhận sinh đúng một Task BACKLOG, campaignId=null. Khi Manager đánh dấu Campaign COMPLETED, chặn tạo mới và tự hủy PENDING có lịch sử; IN_PROGRESS tiếp tục xử lý. Hết ngày kế hoạch không tự hoàn thành Campaign. Quy tắc này thay thế quyết định 2026-10-13 giữ PENDING sau hoàn thành.</p><p>Đây là 1 luồng <strong>bổ sung, độc lập</strong> với luồng Package/Campaign chính — cho phép Client đề xuất thêm 1 bài đăng cụ thể ngoài kế hoạch Campaign đã duyệt.</p><h3 id="_3-5-7-—-create-content-request" tabindex="-1">3.5.7 — Create Content Request <a class="header-anchor" href="#_3-5-7-—-create-content-request" aria-label="Permalink to &quot;3.5.7 — Create Content Request&quot;">​</a></h3><ul><li>Client tạo được bài content mới, chờ Manager coi và quyết định đồng ý làm hay không.</li><li>Nếu đồng ý → chuyển trạng thái <code>accepted</code> để phân chia task cho role khác thực hiện.</li><li><strong>[CONFIRMED 2026-09-15]</strong> Nếu Manager từ chối → <code>denied</code> là trạng thái <strong>cuối (terminal)</strong>, khác với Task reject. Client không sửa lại được request đã denied — phải tạo Content Request mới hoàn toàn nếu muốn đề xuất lại.</li><li>Ghi chú thêm: cần <strong>note lại</strong> để sau này tính vào công việc bổ sung (có thể liên quan đến billing/KPI ngoài phạm vi Package gốc).</li><li><strong>[CONFIRMED 2026-09-14]</strong> Role list trong CSV ghi cả OWNER/MANAGER/CLIENT, nhưng thực tế hành động <strong>Create chỉ do CLIENT thực hiện</strong> — Owner/Manager có mặt trong role list vì họ có quyền TRUY CẬP xem màn hình này (để duyệt), không phải vì họ tự tạo request cho mình.</li></ul><h3 id="_3-5-8-—-track-request-status" tabindex="-1">3.5.8 — Track Request Status <a class="header-anchor" href="#_3-5-8-—-track-request-status" aria-label="Permalink to &quot;3.5.8 — Track Request Status&quot;">​</a></h3><ul><li>Manager điều chỉnh status của yêu cầu do Client đưa lên.</li><li>Luồng trạng thái: <code>pending → in progress → accept</code> (chuyển công việc vào backlog) hoặc <code>denied</code>.</li><li>4 trạng thái (pending / in progress / accept / denied) <strong>do Agency setting quyết định</strong> — Client hoàn toàn không có quyền tự set trạng thái.</li><li>Role: MANAGER.</li><li><strong>Ghi chú kèm theo trong nguồn</strong> (về Template Media Package, liên quan gián tiếp tới luồng): Template media package bao gồm số lượng bài, thời gian thực hiện, chất lượng nội dung... Team truyền thông thảo luận cụ thể hóa các bài viết → ra kế hoạch truyền thông (tiêu đề bài viết, nền tảng đăng tải...) → thảo luận với Client xem kế hoạch có ok không → ra hợp đồng chính thức để ký. Đây là mô tả luồng thực tế ngoài đời mà hệ thống đang số hóa lại qua Package→Campaign.</li></ul><h3 id="_3-5-9-—-update-request" tabindex="-1">3.5.9 — Update Request <a class="header-anchor" href="#_3-5-9-—-update-request" aria-label="Permalink to &quot;3.5.9 — Update Request&quot;">​</a></h3><ul><li>Client điều chỉnh nội dung content muốn thêm vào.</li><li><strong>Chỉ được làm khi đang ở trạng thái PENDING</strong>.</li><li>Role: CLIENT.</li></ul><h3 id="_3-5-10-—-cancel-request" tabindex="-1">3.5.10 — Cancel Request <a class="header-anchor" href="#_3-5-10-—-cancel-request" aria-label="Permalink to &quot;3.5.10 — Cancel Request&quot;">​</a></h3><ul><li>Khi Track Request Status đã đổi khỏi PENDING, Client <strong>không còn quyền xóa/hủy</strong> request nữa — hủy chỉ hợp lệ khi status vẫn là PENDING.</li><li>Role: CLIENT.</li></ul><h2 id="_5-lien-ket-voi-task-backlog" tabindex="-1">5. Liên kết với Task backlog <a class="header-anchor" href="#_5-lien-ket-voi-task-backlog" aria-label="Permalink to &quot;5. Liên kết với Task backlog&quot;">​</a></h2><p><strong>[CONFIRMED 2026-09-14]</strong> Khi Manager set trạng thái Content Request thành <code>accepted</code>, hệ thống <strong>tự động sinh 1 Task mới</strong> trong backlog của Workspace — task này sau đó chảy vào đúng quy trình Task chuẩn (Identify Task Detail → Assign → Approval Sequence...). Xem chi tiết đầy đủ tại <a href="./05-content-task-workflow.html">05-content-task-workflow.md</a>.</p><p>Ngoài nguồn từ Campaign (mục 3) và Content Request (mục 4), Manager còn được tự do thêm Task thủ công trực tiếp vào backlog bất cứ lúc nào (việc nội bộ, không cần qua Campaign hay Content Request) — xem file 05.</p>`,37)])])}const k=n(c,[["render",h]]);export{u as __pageData,k as default};
